import java.util.ArrayList;
import java.util.List;

class TcpReliableDemo {
    static final class Segment {
        final long seq;
        boolean retransmitted;

        Segment(long seq) { this.seq = seq; }
        void markRetransmitted() { retransmitted = true; }
    }

    static final class SackBlocks {
        final List<long[]> blocks = new ArrayList<>();

        static SackBlocks empty() { return new SackBlocks(); }

        static SackBlocks of(long... bounds) {
            SackBlocks sack = new SackBlocks();
            for (int i = 0; i + 1 < bounds.length; i += 2) {
                sack.blocks.add(new long[] { bounds[i], bounds[i + 1] });
            }
            return sack;
        }

        boolean covers(long seq) {
            for (long[] block : blocks) {
                if (seq >= block[0] && seq < block[1]) return true;
            }
            return false;
        }
    }

    static final class Sender {
        long srtt = -1;
        long rttvar = 0;
        long rto = 1000;
        int dupAckCount = 0;
        long highestAck = 0;
        int cwndMss = 10;
        boolean inFastRecovery = false;
        final List<String> events = new ArrayList<>();

        void onRttSample(long rttMs, boolean wasRetransmitted) {
            if (wasRetransmitted) {
                events.add("skip retransmitted RTT sample (Karn)");
                return;
            }
            if (srtt < 0) {
                srtt = rttMs;
                rttvar = rttMs / 2;
            } else {
                long oldSrtt = srtt;
                rttvar = (3 * rttvar + Math.abs(oldSrtt - rttMs)) / 4;
                srtt = (7 * srtt + rttMs) / 8;
            }
            rto = Math.max(1000, srtt + 4 * rttvar);
            events.add("rto=" + rto + "ms");
        }

        void onAck(long ackNum, SackBlocks sack) {
            if (ackNum > highestAck) {
                highestAck = ackNum;
                dupAckCount = 0;
                if (inFastRecovery) exitFastRecovery();
                events.add("advance ack to " + ackNum);
                return;
            }
            if (ackNum == highestAck) {
                dupAckCount++;
                events.add("dupAck=" + dupAckCount + " for gap " + ackNum);
                if (dupAckCount == 3 && !inFastRecovery) {
                    retransmit(ackNum, sack, "fast retransmit");
                    cwndMss = Math.max(2, cwndMss / 2);
                    inFastRecovery = true;
                }
            }
        }

        void onRtoTimeout(Segment seg) {
            retransmit(seg.seq, SackBlocks.empty(), "RTO timeout");
            cwndMss = 1;
            rto = Math.min(rto * 2, 60_000);
            seg.markRetransmitted();
            events.add("backoff rto=" + rto + "ms, cwnd=" + cwndMss + " MSS");
        }

        void retransmit(long seq, SackBlocks sack, String reason) {
            if (sack != null && sack.covers(seq)) {
                events.add("skip already SACKed seq=" + seq);
            } else {
                events.add(reason + ": retransmit seq=" + seq);
            }
        }

        void exitFastRecovery() {
            inFastRecovery = false;
            events.add("exit fast recovery");
        }
    }

    public static void main(String[] args) {
        Sender sender = new Sender();
        sender.onRttSample(80, false);
        sender.onAck(1200, SackBlocks.empty());
        SackBlocks sack = SackBlocks.of(1400, 1600, 1600, 1800);
        sender.onAck(1200, sack);
        sender.onAck(1200, sack);
        sender.onAck(1200, sack);
        sender.onRttSample(90, true);
        sender.onRtoTimeout(new Segment(1800));
        sender.events.forEach(System.out::println);
    }
}
